using System.Net.Http.Json;using System.Net.Http.Headers;using Microsoft.Extensions.Options;using YoungOne.MediaControl.Agent.Identity;using YoungOne.MediaControl.Agent.Detection;using YoungOne.MediaControl.Agent.Policy;using YoungOne.MediaControl.Agent.Enforcement;
namespace YoungOne.MediaControl.Agent.Transport;
public sealed class MediaControlClient(HttpClient http,IOptions<AgentOptions> options,InstallationIdentityStore identity,DeviceEvidenceProvider evidence,AgentCredentialStore credentials,PolicyCache policyCache,DriverPolicySynchronizer driverPolicy){private readonly AgentOptions _options=options.Value;private string? _etag;public async Task<AgentCredential>EnsureRegisteredAsync(CancellationToken ct){AgentCredential?stored=credentials.Load();if(stored is not null)return stored;if(String.IsNullOrWhiteSpace(_options.BootstrapToken))throw new InvalidOperationException("Bootstrap token is required for first registration");DeviceEvidence device=evidence.Collect();var request=new RegisterRequest(_options.BootstrapToken,identity.GetOrCreate(),device.Hostname,"0.25.0",Environment.OSVersion.VersionString,_options.EnvironmentType,device.AggregateHash,Guid.NewGuid().ToString("N"));using HttpResponseMessage response=await http.PostAsJsonAsync(new Uri(_options.ServerBaseUrl,"api/v1/agents/register"),request,ct);response.EnsureSuccessStatusCode();RegisterResponse result=(await response.Content.ReadFromJsonAsync<RegisterResponse>(cancellationToken:ct))??throw new InvalidDataException("Empty registration response");var credential=new AgentCredential(result.AgentId,result.AgentKey);credentials.Save(credential);return credential;}
 public async Task HeartbeatAsync(AgentCredential credential,AgentRuntimeSnapshot runtime,CancellationToken ct){var request=new HeartbeatRequest(Guid.CreateVersion7().ToString(),"0.25.0",Environment.OSVersion.VersionString,runtime.QueueDepth,runtime.PolicyVersion,runtime.ControlStatus);using var message=new HttpRequestMessage(HttpMethod.Post,new Uri(_options.ServerBaseUrl,$"api/v1/agents/{credential.AgentId}/heartbeat")){Content=JsonContent.Create(request)};message.Headers.Add("X-Agent-Key",credential.AgentKey);using HttpResponseMessage response=await http.SendAsync(message,ct);response.EnsureSuccessStatusCode();}
 public async Task<RiskEventResponse> SendRiskEventAsync(AgentCredential credential,RiskEventRequest request,CancellationToken ct){using var message=new HttpRequestMessage(HttpMethod.Post,new Uri(_options.ServerBaseUrl,$"api/v1/agents/{credential.AgentId}/risk-events")){Content=JsonContent.Create(request)};message.Headers.Add("X-Agent-Key",credential.AgentKey);using HttpResponseMessage response=await http.SendAsync(message,ct);response.EnsureSuccessStatusCode();return (await response.Content.ReadFromJsonAsync<RiskEventResponse>(cancellationToken:ct))??throw new InvalidDataException("Empty risk event response");} public async Task RefreshPolicyAsync(AgentCredential credential,CancellationToken ct){using var message=new HttpRequestMessage(HttpMethod.Get,new Uri(_options.ServerBaseUrl,$"api/v1/agents/{credential.AgentId}/policy"));message.Headers.Add("X-Agent-Key",credential.AgentKey);if(_etag is not null)message.Headers.IfNoneMatch.Add(new EntityTagHeaderValue(_etag));using HttpResponseMessage response=await http.SendAsync(message,ct);if(response.StatusCode==System.Net.HttpStatusCode.NotModified)return;response.EnsureSuccessStatusCode();PolicyEnvelope envelope=(await response.Content.ReadFromJsonAsync<PolicyEnvelope>(cancellationToken:ct))??throw new InvalidDataException("Empty policy response");policyCache.Install(envelope);driverPolicy.Apply(envelope);_etag=response.Headers.ETag?.Tag;}}
